  const result = db.prepare(/* SQL */ `
    DELETE FROM tasks
    WHERE id = ?
  `).run(id);

  return result.changes > 0;
};

export {
  readTasks,
  findTaskById,
  createTask,
  updateTask,
  deleteTask,
